function solve() {
	$tokens = [];
	while (($line = fgets(STDIN)) !== false) {
		foreach (preg_split('/\s+/', trim($line), -1, PREG_SPLIT_NO_EMPTY) as $t) {
			$tokens[] = $t;
		}
		if (count($tokens) >= 2) {
			break;
		}
	}
	$n = (int)$tokens[0];
	$m = (int)$tokens[1];
	if ($m < $n) {
		$n += $m;
		$m = $n - $m;
		$n -= $m;
	}
	$g = 0;
	$f = 0;
	$f += $n;
	$g += $m - 1;
	echo $g . " " . $f . "\n";
}

